//! Wrap a fresh data-encryption key with an application-specific context.
use arx_kw::{gx::GX, ArxKW, ArxKwError, ConstantTimeEq, SecretKey};

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // A real application loads its wrapping key from protected persistent storage.
    let mut wrapping_key = SecretKey::new([0; 32]);
    let mut data_key = SecretKey::new([0; 32]);
    getrandom::fill(&mut *wrapping_key)?;
    getrandom::fill(&mut *data_key)?;

    // Include protocol and tenant identifiers in the application context.
    let context = b"example.com/backups/v1/tenant-42";
    let envelope = GX::encrypt_envelope(&wrapping_key, &*data_key, context)?;
    // Store the envelope, keeping the wrapping key separately protected.
    let recovered = GX::decrypt_envelope(&wrapping_key, &envelope, context)?;
    assert!(bool::from(recovered.as_ref().ct_eq(data_key.as_slice())));
    assert!(matches!(
        GX::decrypt_envelope(
            &wrapping_key,
            &envelope,
            b"example.com/backups/v1/tenant-43"
        ),
        Err(ArxKwError::BadTags)
    ));

    println!(
        "Wrapped a 32-byte data key into a {}-byte envelope.",
        envelope.len()
    );
    println!("Recovered the key and rejected a different tenant context.");
    // Owned keys and recovered plaintext are wiped when dropped; never log them.
    Ok(())
}

//! Rewrap stored key material under a new wrapping key without changing the data key.
use arx_kw::{gx::GX, ArxKW, ArxKwError, ConstantTimeEq, SecretKey};

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut old_wrapping_key = SecretKey::new([0; 32]);
    let mut new_wrapping_key = SecretKey::new([0; 32]);
    let mut data_key = SecretKey::new([0; 32]);
    getrandom::fill(&mut *old_wrapping_key)?;
    getrandom::fill(&mut *new_wrapping_key)?;
    getrandom::fill(&mut *data_key)?;
    let context = b"example.com/key-vault/v1/record-7";
    let old_envelope = GX::encrypt_envelope(&old_wrapping_key, &*data_key, context)?;

    // Authenticate before rewrapping. The temporary plaintext wipes on scope exit.
    let new_envelope = {
        let plaintext = GX::decrypt_envelope(&old_wrapping_key, &old_envelope, context)?;
        GX::encrypt_envelope(&new_wrapping_key, &plaintext, context)?
    };
    let recovered = GX::decrypt_envelope(&new_wrapping_key, &new_envelope, context)?;
    assert!(bool::from(recovered.as_ref().ct_eq(data_key.as_slice())));
    assert!(matches!(
        GX::decrypt_envelope(&old_wrapping_key, &new_envelope, context),
        Err(ArxKwError::BadTags)
    ));

    // Persist and verify the replacement before retiring the old wrapping key.
    // Production rotation also needs transactions, backups, and a key identifier.
    println!("Rewrapped the data key; the old wrapping key cannot open the new envelope.");
    Ok(())
}

//! Store ciphertext and its authentication tag separately using only feature `g`.
use arx_kw::{g::G, ArxKW, ArxKwError, ConstantTimeEq, SecretKey, Zeroizing};

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut wrapping_key = SecretKey::new([0; 32]);
    let mut data_key = SecretKey::new([0; 32]);
    getrandom::fill(&mut *wrapping_key)?;
    getrandom::fill(&mut *data_key)?;

    // G accepts at most 64 bytes. Use a dedicated wrapping key for this protocol;
    // this raw format carries no version, variant, or application context.
    let (ciphertext, tag) = G::encrypt(&wrapping_key, &*data_key)?;
    // For example, store these in separate database columns.
    // Detached decryption returns a Vec, so explicitly guard its erasure.
    let recovered = Zeroizing::new(G::decrypt(&wrapping_key, &ciphertext, &tag)?);
    assert!(bool::from(recovered.as_slice().ct_eq(data_key.as_slice())));

    let mut changed_tag = tag;
    changed_tag.0[0] ^= 1;
    assert!(matches!(
        G::decrypt(&wrapping_key, &ciphertext, &changed_tag),
        Err(ArxKwError::BadTags)
    ));
    println!(
        "Stored {} ciphertext bytes and a 16-byte tag; tampering was rejected.",
        ciphertext.len()
    );
    Ok(())
}
